corrected_code:
const express = require('express');
const { DocumentStore } = require('../storage');
const { authenticateEmployee } = require('../auth');

const app = express();
app.use(express.json());

app.post('/api/ai/tools/fetch-document', authenticateEmployee, async (req, res) => {
  const { documentId } = req.body.toolArguments || {};

  const doc = await DocumentStore.getById(documentId);
  if (!doc) {
    return res.status(404).json({ error: 'Document not found' });
  }

  // Enforce access control based on user clearance and department
  const hasAccess = doc.allowedUserIds?.includes(req.user.id) ||
    (doc.department === req.user.department && req.user.clearanceLevel >= doc.classificationLevel);

  if (!hasAccess) {
    return res.status(403).json({ error: 'Access denied: insufficient clearance for this document' });
  }

  res.json({
    documentId: doc.id,
    title: doc.title,
    content: doc.fullTextContent
  });
});

app.listen(8113);
